solution.code:
def summarize(rows: list[dict], key: str, value: str) -> dict[str, dict]:
    acc: dict[str, dict] = {}
    for row in rows:
        if key not in row or row.get(value) is None:
            continue
        v = row[value]
        g = acc.get(row[key])
        if g is None:
            acc[row[key]] = {"count": 1, "sum": v, "max": v}
        else:
            g["count"] += 1
            g["sum"] += v
            g["max"] = max(g["max"], v)
    for g in acc.values():
        g["avg"] = round(g["sum"] / g["count"], 2)
    return acc
